+						return
+					}
+				}
+			case <-ctx.Done():
+				timer.Stop()
+				return
+			case <-timer.C:
+				u.logger.Warn("timed out waiting for sending update")
+			}
+			timer.Stop()
+		}
+	}()
+
+	return metadataUpdates
+}
