+	// TODO: use context, return if it's done
+	var staleShares, newShares []*ssvtypes.SSVShare
+	u.shareStorage.Range(nil, func(share *ssvtypes.SSVShare) bool {
+		if share.Liquidated {
+			return true
+		}
